function packNode(node) {
    if (node.type === "#") {
        return node.text;
    }
    let item = [node.type];
    let hasProps = (Object.keys(node.props).length !== 0);
    if (hasProps) {
        item.push(node.props);
    }
    if (node.children.length === 0) {
        return item;
