function detectRecursion(o1, o2, f) {
  if (arguments.length === 2) {
    f = o2;o2 = undefined;
  }

  if (seen(o1, o2)) {
    return true;
  } else {
    mark(o1, o2);
    try {
      f();
    } finally {
      unmark(o1, o2);
    }
    return false;
  }
}

