  var home = platform.userHomeDirectory();
  var webStormPreferences = io.maximisePath(home, /^\.WebStorm\s*[.\d]+$/, 'config') ||   // windows|unix
    io.maximisePath(home, 'Library', 'Preferences', /^WebStorm\s*[.\d]+$/);               // darwin

