function toURI(obj, dontEncode) {
    const arr = [];
    let paramVal;

    if (isObject(obj) && !isArray(obj)) {
        Object.keys(obj).forEach((val) => {
            if (isArray(obj[val])) {
                paramVal = `[${obj[val].join(',')}]`;
            } else {
                paramVal = obj[val];
            }

            if (dontEncode) {
                arr.push(`${val}=${paramVal}`);
            } else {
                arr.push(
                    `${encodeURIComponent(val)}=${encodeURIComponent(paramVal)}`
                );
            }
        });
    }

    return arr.join('&');
}

