function(options, /* deprecated */listeners) {
        var me = this,
            params = options.params,
            useBatch = me.getBatchActions(),
            model = me.getModel(),
            batch,
            records;

        if (options.operations === undefined) {
            // the old-style (operations, listeners) signature was called
            // so convert to the single options argument syntax
            options = {
                operations: options,
                listeners: listeners
            };

            // <debug warn>
            Ext.Logger.deprecate('Passes old-style signature to Proxy.batch (operations, listeners). Please convert to single options argument syntax.');
            // </debug>
        }

        if (options.batch && options.batch.isBatch) {
            batch = options.batch;
        } else {
            batch = new Ext.data.Batch(options.batch || {});
        }

        batch.setProxy(me);

        batch.on('complete', Ext.bind(me.onBatchComplete, me, [options], 0));
        if (options.listeners) {
            batch.on(options.listeners);
        }

        Ext.each(me.getBatchOrder().split(','), function(action) {
             records = options.operations[action];
             if (records) {
                 if (useBatch) {
                     var operationOptions = {
                         action: action,
                         records: records,
                         model: model
                     };
                     if (params) {
                         operationOptions.params = params;
                     }
                     batch.add(new Ext.data.Operation(operationOptions));
                 } else {
                     Ext.each(records, function(record) {
                         var operationOptions = {
                             action: action,
                             records: [record],
                             model: model
                         };
                         if (params) {
                             operationOptions.params = params;
                         }
                         batch.add(new Ext.data.Operation(operationOptions));
                     });
                 }
             }
        }, me);

        batch.start();
        return batch;
