function calculateFieldColor(selectedColor, nonSelectedColor, focusedColor, index, out)
{
    if(selected.indexOf(index) !== -1 && focused == index)
    return chalk.bold.rgb(selectedColor.r, selectedColor.g, selectedColor.b)(out);
